using System;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Threading;using System.Globalization;using System.Linq;using System.Net.NetworkInformation;using LibreHardwareMonitor.Hardware;
namespace JonsboStudio {
 sealed class SensorSnapshot {public long version;public Dictionary<string,string> values=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);public string Get(string type,string fallback){string value;return values.TryGetValue(SensorBindings.Canonical(type),out value)?value:fallback;}}
 sealed class HardwareSensorReader {
  readonly object gate=new object();readonly bool extra;Computer computer;DateTime sampled=DateTime.MinValue;Dictionary<string,string> values=new Dictionary<string,string>();public string Error="";
  public HardwareSensorReader(bool extra=false,bool gpuOnly=false){this.extra=extra;try{computer=new Computer{IsCpuEnabled=!extra&&!gpuOnly,IsGpuEnabled=gpuOnly,IsStorageEnabled=extra,IsMotherboardEnabled=false};computer.Open();}catch(Exception error){Error=error.Message;try{if(computer!=null)computer.Close();}catch{}computer=null;}}
  public void CopyTo(Dictionary<string,string> target){lock(gate){if(computer==null)return;if((DateTime.UtcNow-sampled).TotalMilliseconds>=900){sampled=DateTime.UtcNow;var next=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);int disk=0;bool cpu=false,gpu=false;foreach(var hardware in computer.Hardware.OrderBy(h=>h.HardwareType.ToString()=="GpuNvidia"?0:h.HardwareType.ToString()=="GpuAmd"?1:2).ThenBy(h=>h.Identifier.ToString(),StringComparer.OrdinalIgnoreCase))try{string type=hardware.HardwareType.ToString();if(!extra&&type=="Cpu"&&!cpu){SensorMapping.Merge(next,SensorMapping.Cpu(SensorMapping.Read(hardware)));cpu=true;}else if(!extra&&type.StartsWith("Gpu",StringComparison.OrdinalIgnoreCase)&&!gpu){SensorMapping.Merge(next,SensorMapping.Gpu(SensorMapping.Read(hardware)));gpu=true;}else if(extra&&type=="Storage"){disk++;var temperature=SensorMapping.Read(hardware).Where(s=>s.type==SensorType.Temperature&&s.value>0&&s.value<150).OrderBy(s=>s.name.IndexOf("Composite",StringComparison.OrdinalIgnoreCase)>=0?0:1).FirstOrDefault();if(temperature!=null&&disk<=2)next[disk==1?"DiskTemp":"DiskTemp2"]=temperature.value.ToString("0",CultureInfo.InvariantCulture);}else if(extra&&type=="Motherboard"){var voltage=SensorMapping.Read(hardware).FirstOrDefault(s=>s.type==SensorType.Voltage&&s.name.IndexOf("Vcore",StringComparison.OrdinalIgnoreCase)>=0);if(voltage!=null)next["CpuVoltage"]=voltage.value.ToString("0.00",CultureInfo.InvariantCulture);}}catch(Exception error){Error=error.Message;}values=next;}SensorMapping.Merge(target,values);}}
 }
 sealed class NetworkSensorReader {
  readonly Dictionary<string,Tuple<long,long>> previous=new Dictionary<string,Tuple<long,long>>();DateTime sampled=DateTime.UtcNow;
  public void CopyTo(Dictionary<string,string> target){DateTime now=DateTime.UtcNow;double seconds=(now-sampled).TotalSeconds;long received=0,sent=0;bool baseline=false;var seen=new HashSet<string>();try{foreach(var adapter in NetworkInterface.GetAllNetworkInterfaces()){if(adapter.OperationalStatus!=OperationalStatus.Up||adapter.NetworkInterfaceType==NetworkInterfaceType.Loopback||adapter.NetworkInterfaceType==NetworkInterfaceType.Tunnel)continue;var properties=adapter.GetIPProperties();if(!properties.GatewayAddresses.Any(g=>!g.Address.Equals(System.Net.IPAddress.Any)&&!g.Address.Equals(System.Net.IPAddress.IPv6Any)))continue;var statistics=adapter.GetIPStatistics();Tuple<long,long> old;if(previous.TryGetValue(adapter.Id,out old)){received+=Math.Max(0,statistics.BytesReceived-old.Item1);sent+=Math.Max(0,statistics.BytesSent-old.Item2);baseline=true;}previous[adapter.Id]=Tuple.Create(statistics.BytesReceived,statistics.BytesSent);seen.Add(adapter.Id);}foreach(string id in previous.Keys.Where(id=>!seen.Contains(id)).ToArray())previous.Remove(id);if(seconds>0&&baseline){target["DownNetSpeed"]=(received/seconds/1024).ToString("0.0",CultureInfo.InvariantCulture);target["UpNetSpeed"]=(sent/seconds/1024).ToString("0.0",CultureInfo.InvariantCulture);}else if(seen.Count==0){target["DownNetSpeed"]="0.0";target["UpNetSpeed"]="0.0";}}catch{}sampled=now;}
 }
 sealed class SensorSampler:IDisposable {
  static readonly Lazy<HardwareSensorReader> hardware=new Lazy<HardwareSensorReader>(()=>new HardwareSensorReader());static readonly Lazy<HardwareSensorReader> gpuHardware=new Lazy<HardwareSensorReader>(()=>new HardwareSensorReader(false,true));static readonly Lazy<HardwareSensorReader> extra=new Lazy<HardwareSensorReader>(()=>new HardwareSensorReader(true));
  readonly object gate=new object();readonly NetworkSensorReader network=new NetworkSensorReader();System.Threading.Timer timer;ulong idleBefore,totalBefore;long version;IntPtr gpu;bool nvml,nvmlInitialized,disposed;public volatile bool IncludeGpuVoltage,IncludeExtraHardware;public volatile SensorSnapshot Latest=new SensorSnapshot();
  [StructLayout(LayoutKind.Sequential)]class MemoryStatus{public uint length=64,load;public ulong total,available,pageTotal,pageAvailable,virtualTotal,virtualAvailable,extended;}
  [StructLayout(LayoutKind.Sequential)]struct GpuUtil{public uint gpu,memory;}
  [DllImport("kernel32.dll")]static extern bool GetSystemTimes(out ulong idle,out ulong kernel,out ulong user);[DllImport("kernel32.dll")]static extern bool GlobalMemoryStatusEx(MemoryStatus status);
  [DllImport("nvml.dll",CallingConvention=CallingConvention.Cdecl)]static extern int nvmlInit_v2();[DllImport("nvml.dll",CallingConvention=CallingConvention.Cdecl)]static extern int nvmlShutdown();[DllImport("nvml.dll",CallingConvention=CallingConvention.Cdecl)]static extern int nvmlDeviceGetHandleByIndex_v2(uint index,out IntPtr handle);
  [DllImport("nvml.dll",CallingConvention=CallingConvention.Cdecl)]static extern int nvmlDeviceGetTemperature(IntPtr handle,uint sensor,out uint value);[DllImport("nvml.dll",CallingConvention=CallingConvention.Cdecl)]static extern int nvmlDeviceGetUtilizationRates(IntPtr handle,out GpuUtil value);[DllImport("nvml.dll",CallingConvention=CallingConvention.Cdecl)]static extern int nvmlDeviceGetClockInfo(IntPtr handle,uint clock,out uint value);[DllImport("nvml.dll",CallingConvention=CallingConvention.Cdecl)]static extern int nvmlDeviceGetPowerUsage(IntPtr handle,out uint value);
  public SensorSampler(bool includeGpuVoltage=false,bool includeExtraHardware=false){IncludeGpuVoltage=includeGpuVoltage;IncludeExtraHardware=includeExtraHardware;try{nvmlInitialized=nvmlInit_v2()==0;if(nvmlInitialized)nvml=nvmlDeviceGetHandleByIndex_v2(0,out gpu)==0;}catch{}Sample(null);timer=new System.Threading.Timer(Sample,null,1000,1000);}
  public static void AddMemory(Dictionary<string,string> values,ulong total,ulong available,uint load){values["MemoryUsage"]=load.ToString(CultureInfo.InvariantCulture);values["AvailableMemoryUsage"]=(100-Math.Min(100,load)).ToString(CultureInfo.InvariantCulture);values["UsedMemory"]=((total-available)/1073741824.0).ToString("0.0",CultureInfo.InvariantCulture);values["TotalMemory"]=(total/1073741824.0).ToString("0.0",CultureInfo.InvariantCulture);values["AvailableMemory"]=(available/1073741824.0).ToString("0.0",CultureInfo.InvariantCulture);SensorBindings.ApplyAliases(values);}
  void Sample(object ignored){lock(gate){if(disposed)return;var next=new SensorSnapshot{version=Interlocked.Increment(ref version)};var d=next.values;try{ulong idle,kernel,user;if(GetSystemTimes(out idle,out kernel,out user)){ulong total=kernel+user;if(totalBefore>0&&total>totalBefore)d["CpuUsage"]=Math.Max(0,Math.Min(100,100*(1-(idle-idleBefore)/(double)(total-totalBefore)))).ToString("0",CultureInfo.InvariantCulture);idleBefore=idle;totalBefore=total;}var memory=new MemoryStatus();if(GlobalMemoryStatusEx(memory))AddMemory(d,memory.total,memory.available,memory.load);d["CurrentTime"]=DateTime.Now.ToString("HH:mm:ss");d["CurrentDates"]=DateTime.Now.ToString("yyyy-MM-dd");d["WeekDaysL3"]=DateTime.Now.ToString("ddd");network.CopyTo(d);if(nvml)try{uint value;GpuUtil util;if(nvmlDeviceGetTemperature(gpu,0,out value)==0&&value>0)d["GPUTemp"]=value.ToString();if(nvmlDeviceGetUtilizationRates(gpu,out util)==0)d["GpuUsage"]=util.gpu.ToString();if(nvmlDeviceGetClockInfo(gpu,0,out value)==0)d["GpuFrequency"]=value.ToString();if(nvmlDeviceGetPowerUsage(gpu,out value)==0)d["GpuTEC"]=(value/1000.0).ToString("0",CultureInfo.InvariantCulture);}catch{}hardware.Value.CopyTo(d);if(IncludeGpuVoltage||!d.ContainsKey("GPUTemp")||!d.ContainsKey("GpuFrequency")||!d.ContainsKey("GpuTEC"))gpuHardware.Value.CopyTo(d);if(IncludeExtraHardware)extra.Value.CopyTo(d);SensorBindings.ApplyAliases(d);}catch{}Latest=next;}}
  public void Dispose(){lock(gate){if(disposed)return;disposed=true;if(timer!=null)timer.Dispose();if(nvmlInitialized)try{nvmlShutdown();}catch{}}}
 }
}
